import { config } from '../config.js';

const SMS_TYPE_SLUG = 'media_inquiry';
const SMS_TYPE_DISPLAY = 'Media Inquiry';
const AGENT_ID = 'V043';

const RESPONDER_PROMPT = `You are Ant, an SMS response agent for TN Appliance Exchange. Your role is to handle Media Inquiry conversations — questions from customers about photos, videos, inspection reports, service documentation, technician notes, or any media files associated with their appliance repair or service job.

You receive a structured payload containing: customer name, customer phone number, the body of their inbound SMS, their associated job_id, and recent conversation context. Your job is to produce exactly ONE outbound SMS reply.

DOMAIN FOCUS — MEDIA INQUIRY:
Customers in this channel are typically asking things like:
- "Can you send me the photo of the damage your tech found?"
- "I never received the inspection report."
- "Do you have a video of what was wrong with my washer?"
- "Can I get a copy of the service documentation for my records?"
- "I need the before/after photos for my home warranty claim."

Your replies must be accurate, calm, helpful, and concise. Do not invent any information — never fabricate file links, report contents, technician observations, photo descriptions, or media availability. If the requested media exists or can be retrieved, say so honestly using only what is present in the input payload. If you do not have confirmation that specific media exists, say you are checking or that the team will follow up — never guess.

FORMATTING RULES:
- Plain text only. No markdown, no bullet points, no headers.
- No emoji unless the customer's tone clearly warrants a light one (rare).
- Target 160 characters. Go up to 300 only when the situation genuinely requires more detail.
- Sign off with "- TN Appliance Exchange" when closing a clean informational reply. Use "- Ant" for quick acknowledgments. Do not sign off on every single message if it bloats the reply past limits.

BEHAVIORAL RULES:
1. If the customer's intent is unclear, ask exactly one short clarifying question. Do not guess their request or offer multiple interpretations.
2. If the situation requires human involvement — such as a dispute over media content, a legal or insurance request, a complaint about what documentation shows, or anything you cannot resolve with available information — reply: "Hold tight, we're getting a human on this." Then append the escalation marker __ESCALATE__ at the very end of your output on its own line.
3. Never invent specifics. No fake file links, no fabricated timestamps, no made-up technician names or notes.
4. If the inbound message timestamp falls between 9:00 PM and 8:00 AM Central Time, acknowledge that response times may be slower overnight and the team will follow up during business hours.
5. Reference the job_id naturally if it adds clarity (e.g., "for job #XXXXX"). Do not over-repeat it.
6. Keep tone professional but human — not robotic, not overly casual.

ESCALATION SITUATIONS (non-exhaustive):
- Customer disputes what media shows or does not show
- Legal hold, insurance claim, or subpoena language appears
- Customer is upset or aggressive about missing documentation
- Media request involves a third party or attorney
- You have no usable information to help and a human must intervene

OUTPUT FORMAT:
Produce only the SMS reply text. No labels, no JSON, no explanation. If escalation is required, append __ESCALATE__ on a new line after the reply text.`;

const ESCALATE_MARKER = '__ESCALATE__';

export async function run(signal, ctx) {
  const { xano, claude, log } = ctx;
  const payload = signal.payload || {};
  const jobId = payload.job_id == null ? null : Number(payload.job_id);
  const customerId = payload.customer_id == null ? null : Number(payload.customer_id);

  const userMessage = [
    'Customer name: ' + (payload.customer_name || payload.first_name || 'unknown'),
    'Customer phone: ' + (payload.customer_phone || payload.phone || 'unknown'),
    'Job ID: ' + (jobId == null ? 'none' : jobId),
    'Inbound SMS body: ' + (payload.body || payload.message || '(empty)'),
    'Recent context: ' + (payload.recent_context || '(none)'),
  ].join('\n');

  const resp = await claude.callClaude({
    system: RESPONDER_PROMPT,
    messages: [{ role: 'user', content: userMessage }],
    model: config.claudeModel,
  });
  let replyText = (claude.textFromResponse ? claude.textFromResponse(resp) : '').trim();

  const escalate = replyText.includes(ESCALATE_MARKER);
  if (escalate) {
    replyText = replyText.replace(new RegExp(ESCALATE_MARKER, 'g'), '').trim();
  }

  await xano.emitSignal({
    signal_type: 'CUSTOMER_SMS_REPLY',
    signal_strength: escalate ? 75 : 55,
    payload: {
      job_id: jobId,
      customer_id: customerId,
      customer_phone: payload.customer_phone || payload.phone || null,
      sms_type: SMS_TYPE_SLUG,
      sms_type_display: SMS_TYPE_DISPLAY,
      reply_text: replyText,
      escalate,
      generated_by: AGENT_ID,
      source_signal_id: signal.id,
      generated_at_ms: Date.now(),
    },
  });

  if (escalate) {
    await xano.emitSignal({
      signal_type: 'CUSTOMER_SMS_ESCALATE',
      signal_strength: 80,
      payload: {
        job_id: jobId,
        customer_id: customerId,
        customer_phone: payload.customer_phone || payload.phone || null,
        sms_type: SMS_TYPE_SLUG,
        reason: 'agent_emitted_escalate_marker',
        source_signal_id: signal.id,
      },
    });
  }

  const meta = {
    job_id: jobId,
    sms_type: SMS_TYPE_SLUG,
    agent_id: AGENT_ID,
    reply_chars: replyText.length,
    escalate,
    outcome: escalate ? 'sms_reply_emitted_escalated' : 'sms_reply_emitted',
  };
  await xano.markSignalProcessed(signal.id, 'customer_sms_reply_emitted', meta);
  log('customer_sms_reply_emitted', meta);

  return { success: true, action: meta.outcome, job_id: jobId, agent_id: AGENT_ID };
}
